package org.apache.commons.codec.binary;

import java.io.*;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.nio.ByteBuffer;
import java.nio.charset.Charset;
import java.util.*;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.Charsets;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_equals_TriageGen0Test {

    @Test
    public void testEquals_SameInstance() {
        String s = "test";
        assertTrue(StringUtils.equals(s, s));
    }

    @Test
    public void testEquals_BothNull() {
        assertTrue(StringUtils.equals(null, null));
    }

    @Test
    public void testEquals_FirstNull() {
        assertFalse(StringUtils.equals(null, "test"));
    }

    @Test
    public void testEquals_SecondNull() {
        assertFalse(StringUtils.equals("test", null));
    }

    @Test
    public void testEquals_BothStrings_Equal() {
        assertTrue(StringUtils.equals("abc", "abc"));
    }

    @Test
    public void testEquals_BothStrings_NotEqual() {
        assertFalse(StringUtils.equals("abc", "def"));
    }

    @Test
    public void testEquals_BothStrings_DifferentLength() {
        assertFalse(StringUtils.equals("abc", "abcd"));
    }

    @Test
    public void testEquals_StringAndStringBuilder_Equal() {
        String s1 = "abc";
        StringBuilder sb2 = new StringBuilder("abc");
        // This triggers the CharSequenceUtils.regionMatches branch
        assertTrue(StringUtils.equals(s1, sb2));
    }

    @Test
    public void testEquals_StringBuilderAndString_Equal() {
        StringBuilder sb1 = new StringBuilder("abc");
        String s2 = "abc";
        // This triggers the CharSequenceUtils.regionMatches branch
        assertTrue(StringUtils.equals(sb1, s2));
    }

    @Test
    public void testEquals_StringBuilderAndStringBuilder_Equal() {
        StringBuilder sb1 = new StringBuilder("abc");
        StringBuilder sb2 = new StringBuilder("abc");
        assertTrue(StringUtils.equals(sb1, sb2));
    }

    @Test
    public void testEquals_StringBuilderAndStringBuilder_NotEqual() {
        StringBuilder sb1 = new StringBuilder("abc");
        StringBuilder sb2 = new StringBuilder("def");
        assertFalse(StringUtils.equals(sb1, sb2));
    }

    @Test
    public void testEquals_DifferentLengths_CharSequence() {
        StringBuilder sb1 = new StringBuilder("abc");
        StringBuilder sb2 = new StringBuilder("abcd");
        // Math.max(3, 4) = 4. regionMatches will return false if lengths differ in logic.
        assertFalse(StringUtils.equals(sb1, sb2));
    }

    @Test
    public void testEquals_EmptyStrings() {
        assertTrue(StringUtils.equals("", ""));
        assertTrue(StringUtils.equals(new StringBuilder(""), new StringBuilder("")));
    }
}
